package org.cgse.core;
import java.math.BigInteger;import java.util.*;
public class GubCoverProbe{
 static BigInteger b(long v){return BigInteger.valueOf(v);}static boolean pass(ExactLinearProgram.Constraint row,BigInteger[] x){BigInteger sum=BigInteger.ZERO;for(var e:row.terms().entrySet())sum=sum.add(e.getValue().multiply(x[e.getKey()]));return sum.compareTo(row.upper())<=0;}
 public static void main(String[] args){Random rnd=new Random(8179387);long cuts=0,feasible=0;for(int test=0;test<1000;test++){int n=4+rnd.nextInt(7);BigInteger[] lo=new BigInteger[n],hi=new BigInteger[n];ExactRational[] point=new ExactRational[n];for(int i=0;i<n;i++){lo[i]=b(rnd.nextInt(4));hi[i]=lo[i].add(BigInteger.ONE);point[i]=ExactRational.of(lo[i]).add(new ExactRational(b(rnd.nextInt(5)),b(4)));}List<ExactLinearProgram.Constraint> rows=new ArrayList<>();for(int start=0;start<n-1;start+=2){Map<Integer,BigInteger> terms=new TreeMap<>();terms.put(start,BigInteger.ONE);terms.put(start+1,BigInteger.ONE);rows.add(new ExactLinearProgram.Constraint(terms,lo[start].add(lo[start+1]).add(BigInteger.ONE)));}BigInteger scale=test%3==0?BigInteger.TEN.pow(40):BigInteger.ONE;for(int r=0;r<1+rnd.nextInt(4);r++){Map<Integer,BigInteger> terms=new TreeMap<>();BigInteger rhs=b(1+rnd.nextInt(25)).multiply(scale);for(int i=0;i<n;i++){BigInteger w=b(1+rnd.nextInt(12)).multiply(scale);terms.put(i,w);rhs=rhs.add(w.multiply(lo[i]));}rows.add(new ExactLinearProgram.Constraint(terms,rhs));}PlanningBudget budget=new PlanningBudget(0,20000000,64L<<20,()->false,()->0L);var generated=CountGubCoverPrototype.separate(rows,lo,hi,point,budget,131072);cuts+=generated.size();for(int mask=0;mask<(1<<n);mask++){BigInteger[] x=lo.clone();for(int i=0;i<n;i++)if((mask&(1<<i))!=0)x[i]=hi[i];if(rows.stream().anyMatch(r->!pass(r,x)))continue;feasible++;for(var cut:generated)if(!pass(cut,x))throw new AssertionError("test="+test+" cut="+cut+" witness="+Arrays.toString(x));}if(budget.reservedBytes()!=0)throw new AssertionError("leak");}System.out.println("GubCoverProbe models=1000 cuts="+cuts+" feasiblePoints="+feasible+" invalid=0 leaks=0");}
}
